import argparse,json,subprocess,zipfile,posixpath,xml.etree.ElementTree as E
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--fixture',type=Path,required=True);p.add_argument('--extraction',type=Path,required=True);p.add_argument('--deck',type=Path,required=True);p.add_argument('--ffmpeg',required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args()
if a.report.exists():raise FileExistsError(a.report)
def dec(f):return subprocess.run([a.ffmpeg,'-v','error','-i',str(f),'-f','rawvideo','-pix_fmt','rgba','-'],capture_output=True,check=True).stdout
truth=dec(a.fixture/'truth-alpha.png');out=dec(a.extraction/'extracted.png');original=(a.fixture/'simulated-scan.png').read_bytes();errs=[abs(truth[j]-out[j]) for j in range(3,len(out),4)];paper=[j for j in range(3,len(out),4) if truth[j]==0];edge=[j for j in range(3,len(out),4) if 1<=truth[j]<=254]
checks={'originalBytesRetained':original==(a.extraction/'original.png').read_bytes(),'alphaMaxError1':max(errs)<=1,'paperAlphaExactlyZero':all(out[j]==0 for j in paper),'faintAlpha12Retained':all(abs(out[j]-12)<=1 for j in range(3,len(out),4) if truth[j]==12),'grayEdgePixelsRetained':all(abs(out[j]-truth[j])<=1 for j in edge),'continuousNotBinaryMask':len(set(out[3::4]))>=128,'whiteInkRGBUnchanged':all(out[j:j+3]==bytes([255]*3) for j in range(0,len(out),4))}
ns={'p':'http://schemas.openxmlformats.org/presentationml/2006/main','a':'http://schemas.openxmlformats.org/drawingml/2006/main'};R='{http://schemas.openxmlformats.org/officeDocument/2006/relationships}embed'
with zipfile.ZipFile(a.deck) as z:
 for i in range(1,5):
  root=E.fromstring(z.read(f'ppt/slides/slide{i}.xml'));pics=root.findall('.//p:pic',ns);checks[f's{i}RealPicture']=len(pics)==1;rels={r.get('Id'):r.get('Target') for r in E.fromstring(z.read(f'ppt/slides/_rels/slide{i}.xml.rels'))};target=rels[pics[0].find('.//a:blip',ns).get(R)];part=target.lstrip('/') if target.startswith('/') else posixpath.normpath(posixpath.join('ppt/slides',target));checks[f's{i}ByteIdenticalEmbedding']=z.read(part)==(original if i==1 else (a.extraction/'extracted.png').read_bytes())
r={'passed':all(checks.values()),'checks':checks,'alphaMaxError':max(errs),'alphaMeanError':sum(errs)/len(errs),'paperPixelCount':len(paper),'grayEdgeCount':len(edge),'alphaLevels':len(set(out[3::4])),'limits':'Original procedural simulated scan with known flat paper and single ink. Not arbitrary scanned handwriting/photo shadow/colored paper texture.'};a.report.write_text(json.dumps(r,indent=2),encoding='utf-8');print(json.dumps(r,indent=2))
